-- =============================================================================
-- sql/77: BOX sticks generator 0.13: the `grid` landing rung and two stick flags
-- =============================================================================
-- PURPOSE   Widen three CHECK constraints of sql/73 so that a set generated by box_sticks_0.13 can be stored:
--             * tvd_rung 'grid' on box.location_stick and box.location_set_bench: a landing taken from the geologist's
--               structure grids, in place of the offset rung or as a bound on a carried landing
--               (box/sticks/grid_rung.py; docs/box_sticks/grid-rung-2026-11-20);
--             * stick flags 'grid_bounded' (a carried landing pulled to the grid) and 'outside_grid' (a landing more
--               than 150 ft outside its bench's gridded interval that was NOT moved).
--           Nothing else changes. No row is rewritten: every existing value satisfies the wider constraints.
-- DEPENDS   sql/73 (box.location_set and its tables).
-- OWNER     app-owned (schema box): written only by scripts.box_sticks_run store, on an explicit go. ETL never touches it.
-- REFRESH   none (plain tables).
-- RUN       python -m scripts.apply_box_sticks_grid_rung [--dry-run]     (explicit authorization required)
-- CHECK     the three constraints list the new values; row counts of the three tables unchanged.
-- Idempotent: each constraint is dropped if present and added again. The swap takes a brief lock on the table and
-- validates existing rows (159,738 stick rows on 2026-11-20).
-- =============================================================================

ALTER TABLE box.location_stick DROP CONSTRAINT IF EXISTS location_stick_tvd_rung_check;
ALTER TABLE box.location_stick ADD CONSTRAINT location_stick_tvd_rung_check
    CHECK (tvd_rung IN ('direct', 'thickness', 'bracket', 'offset', 'grid'));

ALTER TABLE box.location_stick DROP CONSTRAINT IF EXISTS location_stick_flags_check;
ALTER TABLE box.location_stick ADD CONSTRAINT location_stick_flags_check
    CHECK (flags <@ ARRAY['pinned', 'two_landings_observed', 'second_level_nearby', 'dsu_drilled_across', 'grid_bounded', 'outside_grid']);

ALTER TABLE box.location_set_bench DROP CONSTRAINT IF EXISTS location_set_bench_tvd_rung_check;
ALTER TABLE box.location_set_bench ADD CONSTRAINT location_set_bench_tvd_rung_check
    CHECK (tvd_rung IN ('direct', 'thickness', 'bracket', 'offset', 'grid', 'none'));

COMMENT ON COLUMN box.location_stick.tvd_rung IS
    'How the landing depth was set: direct (the bench''s own wells within a mile), thickness / bracket / offset (carried from other benches), or grid '
    '(generator 0.13: the geologist''s structure grids, in place of the offset rung or as a bound on a carried landing; Delaware only).';
